def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    offers = []
    for i in range(m):
        l, r = map(int, lines[1 + i].split())
        offers.append((l, r))

    results = [0] * (n + 1)

    for x in range(1, n + 1):
        occupied = [False] * (n + 2)  # 1-indexed with padding
        total_days = 0

        for l, r in offers:
            # Check if offer length >= x
            if r - l + 1 >= x:
                # Check if entire range [l, r] is unoccupied
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        can_accept = False
                        break

                if can_accept:
                    for day in range(l, r + 1):
                        occupied[day] = True
                    total_days += (r - l + 1)

        results[x] = total_days

    output_lines = [str(results[x]) for x in range(1, n + 1)]
    return '\n'.join(output_lines) + '\n'

def solution(input_text):
    lines = input_text.strip().split('\n')
    idx = 0

    def read_ints():
        nonlocal idx
        result = []
        while True:
            line = lines[idx]
            idx += 1
            if line.strip():
                result.extend(map(int, line.split()))
            elif idx < len(lines) and lines[idx].strip() == '':
                idx += 1
        return result

    t = int(lines[0])
    idx = 1

    output = []

    for _ in range(t):
        # Skip empty line
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1

        n = int(lines[idx])
        idx += 1

        node_info = {}
        for i in range(n):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            if parts[0] == -1:
                node_info[i] = {'type': 'internal', 'left': parts[1], 'right': parts[2]}
            else:
                node_info[i] = {'type': 'leaf', 'value': parts[0]}

        # Count leaves in subtree rooted at node
        def count_leaves(node_idx, memo=None):
            if memo is None:
                memo = {}
            if node_idx in memo:
                return memo[node_idx]
            if node_info[node_idx]['type'] == 'leaf':
                memo[node_idx] = 1
                return 1
            left = node_info[node_idx]['left']
            right = node_info[node_idx]['right']
            memo[node_idx] = count_leaves(left, memo) + count_leaves(right, memo)
            return memo[node_idx]

        # Compute dp[node_idx][is_first] = the optimal value for this subtree
        # is_first = True if it's the first player's turn for this subtree
        #         = False if it's the second player's turn
        def solve(node_idx, is_first, memo=None):
            if memo is None:
                memo = {}
            key = (node_idx, is_first)
            if key in memo:
                return memo[key]

            node = node_info[node_idx]
            if node['type'] == 'leaf':
                memo[key] = node['value']
                return node['value']

            left = node['left']
            right = node['right']

            left_leaves = count_leaves(left, memo)
            right_leaves = count_leaves(right, memo)
            total_moves = left_leaves + right_leaves - 1  # moves needed to finish this subtree

            # Compute values when we have N moves available
            # This corresponds to the recursive structure of the game
            left_result = solve(left, not is_first, memo)
            right_result = solve(right, not is_first, memo)

            if is_first:
                # Current player wants to MAXIMIZE
                # If left + right - 1 is even, we keep the max
                # If odd, we need to switch turns
                if (left_leaves + right_leaves - 1) % 2 == 0:
                    result = max(left_result, right_result)
                else:
                    result = min(left_result, right_result)
                memo[key] = result
            else:
                # Current player wants to MINIMIZE
                if (left_leaves + right_leaves - 1) % 2 == 0:
                    result = min(left_result, right_result)
                else:
                    result = max(left_result, right_result)
                memo[key] = result

            return result

        result = solve(0, True, memo={})
        output.append(str(result))

    return '\n'.join(output)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n0"

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        if len(parts) > 1:
            clauses.append(parts[1:])
        else:
            # A clause with 1 literal -- if it exists on its own, we can pick that
            continue

    total_nodes = 2 * m

    # adj[u] contains implications: u -> v (if u is true, v must be true)
    # But we're building NOT u -> v for a OR b
    adj = [[] for _ in range(total_nodes)]

    def lit_to_node(lit):
        # literal: positive -> 0..m-1, negative -> ^1
        var = abs(lit) - 1
        if lit > 0:
            return var
        else:
            return var ^ 1

    def add_clause(literals):
        if not literals:
            return False
        n = len(literals)
        # For OR(a1, a2, ..., an), add all pairwise implications
        # (a_i OR a_j) -> NOT a_i -> a_j and NOT a_j -> a_i
        for i in range(n):
            for j in range(i + 1, n):
                u = lit_to_node(literals[i])
                v = lit_to_node(literals[j])
                adj[~u].append(v)
                adj[~v].append(u)
        return True

    for clause in clauses:
        if not add_clause(clause):
            return "NO\n0"

    # Kosaraju's algorithm for SCC
    visited = [False] * total_nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(total_nodes):
        if not visited[i]:
            dfs1(i)

    adj_rev = [[] for _ in range(total_nodes)]
    for u in range(total_nodes):
        for v in adj[u]:
            adj_rev[v].append(u)

    visited2 = [False] * total_nodes
    scc_id = [-1] * total_nodes
    scc_count = 0

    def dfs2(u, cid):
        visited2[u] = True
        scc_id[u] = cid
        for v in adj_rev[u]:
            if not visited2[v]:
                dfs2(v, cid)

    for i in range(total_nodes - 1, -1, -1):
        node = order[i]
        if not visited2[node]:
            scc_temp_id = scc_id[:]
            temp_scc_count = scc_count
            dfs2(node, temp_scc_count)
            scc_count += 1

    for i in range(m):
        pos = lit_to_node(i + 1)
        if scc_id[pos] == scc_id[pos ^ 1]:
            return "NO\n" + "0" * m

    assignment = ['0'] * m
    for i in range(m):
        if scc_id[i] < scc_id[i ^ 1]:
            assignment[i] = '1'
        else:
            assignment[i] = '0'

    return "YES\n" + "".join(assignment)

