def solution(input_str):
    import io

    stream = io.StringIO(input_str)

    # Read number of test cases
    t_line = stream.readline()
    if not t_line.strip():
        return ""
    t = int(t_line.strip())

    results = []

    for _ in range(t):
        # Read n and m
        line = stream.readline().split()
        while not line:
            line = stream.readline().split()
        n, m = int(line[0]), int(line[1])

        even_xor = 0
        odd_xor = 0

        # Read the matrix and compute XOR sums by position parity
        for i in range(1, n + 1):
            row_line = stream.readline()
            row = list(map(int, row_line.split()))
            for j in range(1, m + 1):
                val = row[j - 1]
                if (i + j) % 2 == 0:
                    even_xor ^= val
                else:
                    odd_xor ^= val

        # If any subgame has non-zero XOR, first player (Ashish) wins
        if even_xor > 0 or odd_xor > 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

from collections import Counter, deque, defaultdict
import sys

sys.setrecursionlimit(5000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))

    # Check if multisets match
    if Counter(a) != Counter(b):
        return "-1\n"

    # Basic sanity checks
    a.sort()
    b.sort()
    if any(x % 2 != y % 2 for x, y in zip(a, b)):
        return "-1\n"

    if Counter(a) != Counter(b):
        # Try to match by parity more flexibly
        initial_by_parity = defaultdict(list)
        for x in a:
            initial_by_parity[x % 2].append(x)

        target_by_parity = defaultdict(list)
        for x in b:
            target_by_parity[x % 2].append(x)

        for p in [0, 1]:
            if len(initial_by_parity[p]) != len(target_by_parity[p]):
                return "-1\n"

    initial_state = defaultdict(int)
    for x in a:
        initial_state[x] += 1

    target_state = defaultdict(int)
    for x in b:
        target_state[x] += 1

    initial_tuple = tuple(sorted(initial_state.items()))
    target_tuple = tuple(sorted(target_state.items()))

    if initial_tuple == target_tuple:
        return "0\n"

    queue = deque([(initial_state, [])])
    visited = {initial_tuple}

    while queue:
        current_state, path = queue.popleft()
        current_tuple = tuple(sorted(current_state.items()))

        if current_tuple == target_tuple:
            return f"{len(path)}\n" + "\n".join(f"{p} {c}" for p, c in path)

        if len(path) >= 1000:
            continue

        positions = list(current_state.keys())

        # Try all ordered pairs as (source, center)
        for i in range(len(positions)):
            for j in range(len(positions)):
                if i == j:
                    continue

                y = positions[j]
                x = positions[i]

                if current_state[x] > 0 and current_state[y] > 0:
                    new_x = 2 * y - x
                    if abs(new_x) > 10**18:
                        continue

                    new_state = current_state.copy()
                    new_state[x] -= 1
                    if new_state[x] == 0:
                        del new_state[x]
                    new_state[new_x] = new_state.get(new_x, 0) + 1

                    new_tuple = tuple(sorted(new_state.items()))

                    if new_tuple not in visited:
                        visited.add(new_tuple)
                        queue.append((new_state, path + [(x, y)]))

    return "-1\n"


