    """Generate all potentially valid diagonal squares"""
    squares = []

    for center_r in range(n_rows):
        for center_c in range(n_cols):
            for size in range(1, min(n_rows, n_cols)):
                # Get border cells for a diagonal square centered at (center_r, center_c) with size
                border_cells = set()

                # Four edges, each at 45 degrees
                for r in range(center_r - size + 1, center_r + size + 1):
                    for t in range(center_c - size + 1, center_c + size + 1):
