def find_diagonal_squares_v2(grid, n_rows, n_cols):
    """Find all diagonal squares"""
    n_rows = len(grid)
    n_cols = len(grid[0])

    squares = set()

    # Try all possible diagonal squares
    for center_r in range(n_rows):
        for center_c in range(n_cols):
