                border_cells = set()

                # Check 45-degree boundary
                for r in range(center_r - size + 1, center_r + size + 1):
                    # For a diagonal square, border cells at Manhattan distance = size from center
                    c_start = center_c - size + abs(r - center_r)
                    c_end = center_c + size - abs(r - center_r)

