def find_axis_aligned_squares_v2(grid, n_rows, n_cols):
    """Find all axis-aligned squares of size at least 2x2"""
    squares = set()

    for size in range(2, min(n_rows, n_cols) + 1):
        for r_start in range(n_rows - size + 1):
            for c_start in range(n_cols - size + 1):
                border_cells = set()
                is_valid = True

                # Check top row
                for c in range(c_start, c_start + size):
                    border_cells.add((r_start, c))
                    if grid[r_start][c] == '0':
                        is_valid = False
                        break
                if not is_valid:
                    continue

                # Check bottom row
                for c in range(c_start, c_start + size):
                    border_cells.add((r_start + size - 1, c))
                    if grid[r_start + size - 1][c] == '0':
                        is_valid = False
                        break
                if not is_valid:
                    continue

                # Check left column
                for r in range(r_start + 1, r_start + size - 1):
                    border_cells.add((r, c_start))
                    if grid[r][c_start] == '0':
                        is_valid = False
                        break
                if not is_valid:
                    continue

                # Check right column
                for r in range(r_start + 1, r_start + size - 1):
                    border_cells.add((r, c_start + size - 1))
                    if grid[r][c_start + size - 1] == '0':
                        is_valid = False
                        break
                if not is_valid:
                    continue

                # Check isolation
                if is_isolated(grid, border_cells, n_rows, n_cols):
                    squares.add(frozenset(border_cells))

    return squares


def find_diagonal_squares_count(grid, n_rows, n_cols):
    """Count all diagonal (rotated 45°) squares"""
    squares = set()

    for center_r in range(n_rows):
        for center_c in range(n_cols):
            for radius in range(1, min(n_rows, n_cols)):
                # For diagonal square, border cells have Manhattan distance = radius from center
                border_cells = set()

