def is_isolated_grid(grid, border_cells, n_rows, n_cols):
    """Check if no cells outside border_cells but adjacent to any border cell has value '1'"""
    visited = set()
    queue = deque(border_cells)
    visited.update(border_cells)

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n_rows and 0 <= nc < n_cols and (nr, nc) not in visited:
                if grid[nr][nc] == '1':
                    return False
                visited.add((nr, nc))

    return True


def find_axis_aligned(grid, n_rows, n_cols):
