    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse segments: each type 1 event marks the boundary between segments
    segments = []
    current_segment = []

    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '1':
            # Type 1 event: end current segment, start new one
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            # Type 2 event: friend visits during current segment
            current_segment.append(parts[1])
    if current_segment:
        segments.append(current_segment)

    # Collect all unique friend names
    all_names = set()
    for seg in segments:
        all_names.update(seg)

    # Map names to IDs for bitmask operations
    all_names = sorted(all_names)
    name_to_id = {name: i for i, name in enumerate(all_names)}
    num_friends = len(all_names)

    # Build conflict bitmask: conflict[i] has bit j set if i and j co-occur in some segment
    conflict = [0] * num_friends
    for seg in segments:
        ids = sorted([name_to_id[n] for n in seg if n in name_to_id])
        for i_bit in range(len(ids)):
            for j_bit in range(i_bit + 1, len(ids)):
                u, v = ids[i_bit], ids[j_bit]
                conflict[u] |= (1 << v)
                conflict[v] |= (1 << u)

    # Memoized maximum independent set using recursion
    memo = {}

    def rec(mask):
        if mask == 0:
            return 0
        if mask in memo:
            return memo[mask]

        # Find the lowest bit (first friend in the current set)
        i = (mask & -mask).bit_length() - 1

        # Option 1: exclude friend i from the solution
        option1 = rec(mask & ~(1 << i))

        # Option 2: include friend i in the solution (and exclude all friends that conflict with i)
        option2 = 1 + rec(mask & ~(1 << i) & ~conflict[i])

        memo[mask] = max(option1, option2)
        return memo[mask]

    return str(rec((1 << num_friends) - 1))

