def solution(statement):
    lines = statement.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Build adjacency list for good pairs (1-indexed positions)
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Function to get prime factorization
    def get_prime_factors(x):
        factors = defaultdict(int)
        d = 2
        tmp = x
        while d * d <= tmp:
            while tmp % d == 0:
                factors[d] += 1
                tmp //= d
            d += 1
        if tmp > 1:
            factors[tmp] += 1
        return factors

    # Count prime factors at each position
    prime_counts = []  # i-indexed list where each entry is {prime: count}
    all_primes = set()

    for i, x in enumerate(a):
        pf = get_prime_factors(x)
        prime_counts.append(pf)
        all_primes.update(pf.keys())

    total_ops = 0

    # For each prime, compute max flow in bipartite graph
    for p in all_primes:
        # Identify odd positions (1-indexed) and even positions with this prime
        left_nodes = []  # odd positions
        right_nodes = []  # even positions

        for i, pf in enumerate(prime_counts):
            pos = i + 1  # 1-indexed position
            count = pf.get(p, 0)
            if count > 0:
                if pos % 2 != 0:
                    left_nodes.append((i, count))
                else:
                    right_nodes.append((i, count))

        if not left_nodes or not right_nodes:
            continue

        # Build flow network
        source = n * 2
        sink = n * 2 + 1
        capacity = defaultdict(int)  # capacity[u][v]

        # Edges from source to odd positions (capacity = count of prime p at that position)
        for node in left_nodes:
            capacity[source][node[0]] = node[1]

        # Edges from even positions to sink
        for node in right_nodes:
            capacity[node[0]][sink] = node[1]

        # Edges between connected positions (capacity = infinity)
        for u_idx in range(n):
            for v in adj[u_idx + 1]:  # 1-indexed
                if capacity[u_idx][v - 1] == 0:
                    capacity[u_idx][v - 1] = float('inf')

        # Dinic's algorithm for max flow
        level = {}
        ptr = {}

        def bfs():
            nonlocal level, ptr
            level = {u: -1 for u in capacity}
            level[source] = 0
            queue = deque([source])
            while queue:
                u = queue.popleft()
                for v in capacity[u]:
                    if capacity[u][v] > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        queue.append(v)
            return sink in level

        def dfs(u, pushed):
            nonlocal ptr
            if pushed == 0:
                return 0
            if u == sink:
                return pushed
            for v in range(len(capacity[u])):
                if ptr[u] != v:
                    if level[u] + 1 == level[v] and capacity[u][v] > 0:
                        tr = dfs(v, min(pushed, capacity[u][v]))
                        if tr > 0:
                            capacity[u][v] -= tr
                            capacity[v][u] += tr
                            return tr
            return 0

        while bfs():
            ptr = {u: 0 for u in capacity}
            while True:
                pushed = dfs(source, float('inf'))
                if pushed == 0:
                    break
                total_ops += pushed

    return str(total_ops) + '\n'

