    lines = input_data.strip().split('\n')
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])

    MOD = 998244353

    def power(base, exp):
        result = 1
        base %= MOD
        while exp > 0:
            if exp & 1:
                result = (result * base) % MOD
            base = (base * base) % MOD
            exp >>= 1
        return result

    def modinv(a):
        return power(a, MOD - 2)

    p = (a * modinv(b)) % MOD
    q = (1 - p + MOD) % MOD

    fact = [1] * (n + 1)
    invFact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD
    invFact[n] = modinv(fact[n])
    for i in range(n - 1, -1, -1):
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invFact[k] % invFact[n - k] % MOD

    # dp[k] = expected additional games for k players
    dp = [0] * (n + 1)

    for k in range(2, n + 1):
        initial = (k * (k - 1) // 2) % MOD
        dp[k] = initial

        # Expected from recursive processing
        recursive = 0
        for j in range(1, k):
            # First component size j
            first_comp_prob = (p ** j) % MOD * (q ** (k - j)) % MOD
            recursive = (recursive + C(k, j) % MOD * first_comp_prob % MOD * dp[j]) % MOD

        dp[k] = (dp[k] + recursive) % MOD

    return str(dp[n] % MOD)

