def get_neighbors(x: int, y: int, n: int, m: int) -> list:
    """Get all valid neighboring squares for a chip at position (x, y)"""
    result = []
    if x > 1: result.append((x - 1, y))
    if x < n: result.append((x + 1, y))
    if y > 1: result.append((x, y - 1))
    if y < m: result.append((x, y + 1))
    return result

def get_neighbors_glued(x: int, y: int, n: int, m: int, freeze: Set[Tuple[int, int]]) -> list:
    """Get all valid neighboring squares that are not glued"""
    neighbors = get_neighbors(x, y, n, m)
    return [pos for pos in neighbors if pos not in freeze]

def can_move_chip1(x1: int, y1: int, x2: int, y2: int, freeze: Set[Tuple[int, int]], n: int, m: int) -> bool:
    """Check if chip1 can still make a move"""
    return any(get_neighbors_glued(x1, y1, n, m, freeze))

def can_move_chip2(x2: int, y2: int, freeze: Set[Tuple[int, int]], n: int, m: int) -> bool:
    """Check if chip2 can still make a move"""
    return any(get_neighbors_glued(x2, y2, n, m, freeze))

