    n, m, x1, y1, x2, y2 = map(int, parts[:6])

    # If chips start at same position (shouldn't happen per problem)
    if (x1, y1) == (x2, y2):
        return "First\n"

    freeze = frozenset()  # Empty set initially

    @lru_cache(maxsize=None)
    def first_can_win(x1: int, y1: int, x2: int, y2: int, freeze: tuple, turn: int, depth: int) -> int:
        """
        Returns -1 if First can win, 1 if Second wins
        turn: 0 = First's turn, 1 = Second's turn
        """
        # Cycle detection - limit search depth
        cycle_limit = 1000
        if depth > cycle_limit:
            # If First player still can make moves, assume they might win
            if can_move_chip1(x1, y1, x2, y2, freeze, n, m) or can_move_chip2(x2, y2, freeze, n, m):
                return -1
            return 1

        freeze_set = set(freeze)

        # Check winning condition: both chips in same square
        if (x1, y1) == (x2, y2):
            return -1  # First wins

        # Check if First player loses: both chips glued
        if not can_move_chip1(x1, y1, x2, y2, freeze, n, m) and not can_move_chip2(x2, y2, freeze, n, m):
            return 1  # Second wins

        if turn == 0:  # First player's turn
            best_for_first = True  # Assume First can win
            for (nx, ny) in get_neighbors_glued(x1, y1, n, m, freeze):
                result = first_can_win(nx, ny, x2, y2, freeze_set + ((nx, ny),), 1, depth + 1)
                if result == -1:
                    return -1  # Found a winning move
            if not can_move_chip1(x1, y1, x2, y2, freeze, n, m):
                return 1  # No valid moves
            return 1  # Second wins if no guaranteed path

        else:  # Second player's turn
            best_for_second = True  # Assume Second can prevent First from winning
            for (nx, ny) in get_neighbors_glued(x2, y2, n, m, freeze):
                result = first_can_win(x1, y1, nx, ny, freeze_set + ((nx, ny),), 0, depth + 1)
                if result == -1:
                    return -1  # First found a way to win
            if not can_move_chip2(x2, y2, freeze, n, m):
                return 1  # Second wins if stuck
            return 1  # Second wins if they can prevent First from winning

    result = first_can_win(x1, y1, x2, y2, frozenset(), 0, 1)
