def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    if a == b:
        return '0\n'

    # Dijkstra's algorithm to find minimum moves from a to b
    # dist[v] = minimum moves to reach value v from a
    dist = {}
    dist[a] = 0
    pq = [(0, a)]  # (moves, current_value)

    while pq:
        moves, curr = heapq.heappop(pq)

        if curr == b:
            return str(moves) + '\n'

        if moves > dist.get(curr, float('inf')):
            continue

        # Move 1: subtract 1
        next_val = curr - 1
        if next_val >= b:
            if next_val not in dist or moves + 1 < dist[next_val]:
                dist[next_val] = moves + 1
                heapq.heappush(pq, (moves + 1, next_val))

        # Move 2: subtract (curr mod x_i) for each x_i
        for xi in x:
            remainder = curr % xi
            if remainder > 0:  # Only valid if remainder is positive
                next_val = curr - remainder
                if next_val >= b:
                    if next_val not in dist or moves + 1 < dist[next_val]:
                        dist[next_val] = moves + 1
                        heapq.heappush(pq, (moves + 1, next_val))

    # Edge case where we can't reach exactly b (shouldn't happen given problem constraints)
    return str(dist.get(b, float('inf'))) + '\n'

