    def __init__(self, n, A, B):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.A = A
        self.B = B
        self.left_max_A = [float('-inf')] * (2 * self.size)
        self.left_max_B = [float('-inf')] * (2 * self.size)
        self.max_val = [float('-inf')] * (2 * self.size)

        # Initialize leaves
        for i in range(n):
            self.left_max_A[self.size + i] = A[i]
            self.left_max_B[self.size + i] = B[i]

        # Build tree
        for i in range(self.size - 1, 0, -1):
            self._merge(i)

    def _merge(self, node):
        self.left_max_A[node] = max(self.left_max_A[2*node], self.left_max_A[2*node+1])
        self.left_max_B[node] = max(self.left_max_B[2*node], self.left_max_B[2*node+1])
        # For max_val, we need max of left.max_val, right.max_val, and cross terms
        # Left's max_A + Right's max_B (for i < j where i is in left, j in right)
        cross = self.left_max_A[2*node] + self.left_max_B[2*node+1]
        self.max_val[node] = max(self.max_val[2*node], self.max_val[2*node+1], cross)

    def query(self, l, r):
        """Query max A[i] + B[j] for l <= i < j <= r"""
        return self._query(1, 0, self.size - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return float('-inf')
        if l <= start and end <= r:
            return self.max_val[node]

        mid = (start + end) // 2

        # Query both sides
        left_res = self._query(2*node, start, mid, l, r)
        right_res = self._query(2*node+1, mid+1, end, l, r)

        # Handle partial coverage case
        if left_res < float('-inf'):
            # Only right side was queried
            # We need max value from the right part that's fully contained in query
            # Left side might be partially or fully outside
            return right_res
        if right_res < float('-inf'):
            return left_res

        # Both sides have valid results, merge
        return max(left_res, right_res, path_cross_query(2*node, start, mid, l, r, right_res))


