MOD = 10**9 + 7

class ConcatResult:
    def __init__(self, value, length):
        self.value = value
        self.length = length

class ExpressionParser:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        left = self.parse_term()
        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            right = self.parse_term()
            left = self.concat(left, right)
        return left

    def parse_term(self):
        num_str, end = self.parse_number()

        if end >= len(self.s):
            return ConcatResult(int(num_str), len(num_str))

        if self.s[end] == '-':
            self.pos = end + 1
            right_str, end = self.parse_number()
            l = int(num_str)
            r = int(right_str)
            return self.compute_range(l, r)
        elif self.s[end] == '(':
            self.pos = end + 1
            expr = self.parse_expression()
            if self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1
            return self.compute_repeat(num_str, expr)

        return ConcatResult(int(num_str), len(num_str))

    def parse_number(self):
        start = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return self.s[start:self.pos], self.pos

    def concat(self, a, b):
        power = pow(10, b.length, MOD)
        new_value = (a.value * power + b.value) % MOD
        new_length = a.length + b.length
        return ConcatResult(new_value, new_length)

    def compute_range(self, l, r):
        total_value = 0
        total_length = 0

        for i in range(l, r + 1):
            s_i = str(i)
            length = len(s_i)
            total_length += length
            power = pow(10, length, MOD)
            total_value = (total_value * power + int(s_i)) % MOD

        return ConcatResult(total_value, total_length)

    def compute_repeat(self, n_str, expr):
        n = int(n_str)
        L = expr.length
        V = expr.value

        if L == 0 or n == 0:
            return ConcatResult(0, 0)

        denom = (10**L - 1) % MOD
        denom_inv = pow(denom, MOD - 2, MOD)

        exponent = (L * n) % (MOD - 1)
        numerator = (pow(10, exponent, MOD) - 1 + MOD) % MOD

        total_value = (V * numerator * denom_inv) % MOD
        total_length = n * L
        return ConcatResult(total_value, total_length)

