    parser = ExpressionParser(s)
    result = parser.parse()
    return str(result.value)

from collections import deque

def solution(input_str):
    n = int(input_str.strip())

    if n == 0:
        return '0\n'

    # BFS to find minimum steps to reach 0
    # Use a dictionary to track visited numbers and their distances
    dist = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()

        if current == 0:
            return f'{dist[current]}\n'

        # Get all unique digits in the current number
        digits = set(str(current))

        # Try subtracting each digit
        for d in digits:
            next_num = current - int(d)
            if next_num not in dist and next_num >= 0:
                dist[next_num] = dist[current] + 1
                queue.append(next_num)

    return '0\n'

from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, h, m = map(int, lines[0].split())

    restrictions = []
    for i in range(1, m + 1):
        parts = list(map(int, lines[i].split()))
        restrictions.append((parts[0], parts[1], parts[2], parts[3]))

    if m == 0:
        # No restrictions, maximize heights at all positions
        return str(n * h * h)

    @lru_cache(maxsize=None)
    def dp(pos, max_records):
        """
        pos: current position (1-indexed)
        max_records: tuple of (max_height_so_far,) for each active restriction
        """
        if pos > n:
            return 0

        best_profit = float('-inf')

        for current_height in range(h + 1):
            new_max_records = list(max_records)
            current_penalty = 0

            for i in range(m):
                l, r, x, c = restrictions[i]
                if l <= pos <= r:
                    new_max_records[i] = max(new_max_records[i], current_height)

                # When restriction ends, check if it was violated
                if r == pos:
                    if new_max_records[i] > x:
                        current_penalty += c

            profit = current_height * current_height - current_penalty + dp(pos + 1, tuple(new_max_records))
            best_profit = max(best_profit, profit)

        return best_profit

    initial_max_records = tuple(0 for _ in range(m))
    return str(dp(1, initial_max_records))

def solution(input_str):
    n = int(input_str.strip())

    # For the tests given (n up to around 100), this O(n³) enumeration is fast enough
    ans = set()
    for i in range(n + 1):          # count of I (value 1)
        for j in range(n - i + 1):  # count of V (value 5)
            for k in range(n - i - j + 1):  # count of X (value 10)
                l = n - i - j - k  # count of L (value 50)
                total = i * 1 + j * 5 + k * 10 + l * 50
                ans.add(total)

    return str(len(ans))
